class controls_ControlEngine(ICopy):
    __slots__ = ('last_action_count_', 'rules_', 'pid_states_', 'named_vars_', 'expressions_', 'expr_index_', 'last_parse_error_', 'premise_groups_', 'premise_results_', 'rule_premise_offset_', 'total_premises_', 'rule_results_', 'link_time_last_set_', 'control_value_', 'set_point_', 'eval_date_', 'cur_date_', 'cur_time_', 'elapsed_days_', 'pending_actions_', 'action_slots_', )

    def __init__(self):
        self.last_action_count_ = 0
        self.rules_ = None
        self.pid_states_ = None
        self.named_vars_ = None
        self.expressions_ = None
        self.expr_index_ = None
        self.last_parse_error_ = None
        self.premise_groups_ = None
        self.premise_results_ = None
        self.rule_premise_offset_ = None
        self.total_premises_ = 0
        self.rule_results_ = None
        self.link_time_last_set_ = None
        self.control_value_ = 0.0
        self.set_point_ = 0.0
        self.eval_date_ = 0.0
        self.cur_date_ = 0.0
        self.cur_time_ = 0.0
        self.elapsed_days_ = 0.0
        self.pending_actions_ = None
        self.action_slots_ = None

    def evaluate(self, ctx, current_date, dt, rule_time_reached):
        if not rule_time_reached:
            self.last_action_count_ = 0
            return 0
        self.eval_date_ = current_date
        self.cur_date_ = Math_Floor_d(current_date)
        self.cur_time_ = current_date - self.cur_date_
        self.elapsed_days_ = current_date - ctx.options.start_date
        current_time = current_date
        dt_days = (dt / F_constants_SEC_PER_DAY if F_constants_SEC_PER_DAY else fdiv0(dt, F_constants_SEC_PER_DAY))
        half_step = (dt_days / 2.0)
        self.pending_actions_.clear()
        v__r1 = self.premise_groups_
        v__i2_n = v__r1.n
        for v__i2 in range(0, v__i2_n):
            g = v__r1.a[v__i2]
            self.batchEvaluateGroup(g, ctx, current_time, half_step)
        r = 0
