    def refreshReportedSpecies(self):
        self.reported_species_names.clear()
        p = 0
        while p < self.n_pollutants():
            self.reported_species_names.push_back(self.pollutant_names.name_of(p).Clone())
            p += 1
        if self.options.water_age:
            self.reported_species_names.push_back(NewStr_CPtr(R_Lit('__WATER_AGE__')))
        if self.options.heat_transport:
            self.reported_species_names.push_back(NewStr_CPtr(R_Lit('__TEMPERATURE__')))
        self.reactions.reported_species.clear()
        m = 0
        while m < self.reactions.n_species():
            if (not (self.reactions.report_enabled.n == 0)) and (not (self.reactions.report_enabled.a[m & 0xFFFFFFFFFFFFFFFF] != 0)):
                m += 1
                continue
            self.reactions.reported_species.push_back(m)
            self.reported_species_names.push_back(self.reactions.species_name.a[m & 0xFFFFFFFFFFFFFFFF].Clone())
            m += 1


    def n_reported_species(self):
        return ((self.reported_species_names.n + 0x80000000 & 0xFFFFFFFF) - 0x80000000)


    def logControlAction(self, e):
        if self.control_log.n >= SimulationContext_kMaxControlLog:
            self.control_log_dropped = ((self.control_log_dropped + 1) & 0xFFFFFFFFFFFFFFFF)
            return
        self.control_log.push_back(e.Clone())


    def finalize_max_stats(self):
        k = 0
        for k in range(0, SimulationContext_MAX_STATS):
            _o1 = SimulationContext_MaxStats__new()
            _o1.obj_type = 0
            _o1.index = -1
            _o1.value = -1.0
            self.max_courant_crit[k].MoveFrom(_o1)
            _o2 = SimulationContext_MaxStats__new()
            _o2.obj_type = 1
            _o2.index = -1
            _o2.value = -1.0
            self.max_flow_turns[k].MoveFrom(_o2)
            _o3 = SimulationContext_MaxStats__new()
            _o3.obj_type = 0
            _o3.index = -1
            _o3.value = 0.0
            self.max_non_converged[k].MoveFrom(_o3)
