    def add_lstep_sample(self, j, dt, dur, rs):
        u = (j & 0xFFFFFFFFFFFFFFFF)
        if (self.stat_lstep_time.a[u] <= 0.0) or (dt < self.stat_lstep_min.a[u]):
            self.stat_lstep_min.a[u] = dt
        if dt > self.stat_lstep_max.a[u]:
            self.stat_lstep_max.a[u] = dt
        self.stat_lstep_dt_time.a[u] += dt * dur
        self.stat_lstep_time.a[u] += dur
        self.stat_lstep_bin_time.a[((u * (LinkData_N_LSTEP_BINS & 0xFFFFFFFFFFFFFFFF)) + (LinkData_lstep_bin(dt, rs) & 0xFFFFFFFFFFFFFFFF)) & 0xFFFFFFFFFFFFFFFF] += dur


    def count(self):
        return ((self.type_.n + 0x80000000 & 0xFFFFFFFF) - 0x80000000)


    def resize(self, n):
        un = (n & 0xFFFFFFFFFFFFFFFF)
        self.type_.assign_ul_T(un, 0)
        self.node1.assign_ul_T(un, -1)
