    def Assign(self, s):
        if self is s:
            return
        self.storages.Assign(s.storages)
        self.outfalls.Assign(s.outfalls)
        self.dividers.Assign(s.dividers)
        self.subtype_row.Assign_VecT(s.subtype_row)


    def MoveFrom(self, s):
        if self is s:
            return
        self.storages = s.storages
        s.storages = StorageData__new()
        self.outfalls = s.outfalls
        s.outfalls = OutfallData__new()
        self.dividers = s.dividers
        s.dividers = DividerData__new()
        self.subtype_row = s.subtype_row
        s.subtype_row = NewVecI()


    def clear(self):
        self.storages.clear()
        self.outfalls.clear()
        self.dividers.clear()
        self.subtype_row.clear()


    def rebuild_index(self, n_nodes):
        self.subtype_row.assign_ul_T(n_nodes & 0xFFFFFFFFFFFFFFFF, -1)
        r = 0
        while r < self.storages.count():
            self.subtype_row.a[self.storages.node_idx.a[r & 0xFFFFFFFFFFFFFFFF] & 0xFFFFFFFFFFFFFFFF] = r
            r += 1
        r_2 = 0
        while r_2 < self.outfalls.count():
            self.subtype_row.a[self.outfalls.node_idx.a[r_2 & 0xFFFFFFFFFFFFFFFF] & 0xFFFFFFFFFFFFFFFF] = r_2
            r_2 += 1
        r_3 = 0
        while r_3 < self.dividers.count():
            self.subtype_row.a[self.dividers.node_idx.a[r_3 & 0xFFFFFFFFFFFFFFFF] & 0xFFFFFFFFFFFFFFFF] = r_3
            r_3 += 1


    def set_node_type(self, nodes, i, t):
        ui = (i & 0xFFFFFFFFFFFFFFFF)
        if i >= ((self.subtype_row.n + 0x80000000 & 0xFFFFFFFF) - 0x80000000):
            self.subtype_row.resize_ul_T(((i & 0xFFFFFFFFFFFFFFFF) + 1) & 0xFFFFFFFFFFFFFFFF, -1)
        if (t != 0) and (ui < nodes.storage_area.n):
            nodes.storage_area.a[ui] = 0.0
        old = nodes.type_.a[ui]
        existing = self.subtype_row.a[ui]
        if (old == t) and (existing >= 0):
            return existing
        shifted = False
        if existing >= 0:
            if old == 3:
                self.storages.erase_at(existing)
            elif old == 1:
                self.outfalls.erase_at(existing)
            elif old == 2:
                self.dividers.erase_at(existing)
            else:
                pass
            shifted = True
        nodes.type_.a[ui] = t
        row = (-1)
        if t == 3:
            row = self.storages.add_default(i)
            if row != (((self.storages.count() - 1) + 0x80000000 & 0xFFFFFFFF) - 0x80000000):
                shifted = True
        elif t == 1:
            row = self.outfalls.add_default(i)
            if row != (((self.outfalls.count() - 1) + 0x80000000 & 0xFFFFFFFF) - 0x80000000):
                shifted = True
        elif t == 2:
            row = self.dividers.add_default(i)
            if row != (((self.dividers.count() - 1) + 0x80000000 & 0xFFFFFFFF) - 0x80000000):
                shifted = True
        elif t == 0:
            pass
        else:
            pass
        if shifted:
            self.rebuild_index(nodes.count())
            return ((-1) if (t == 0) else self.subtype_row.a[ui])
        self.subtype_row.a[ui] = row
        return row


    def storage_row(self, i):
        if (i >= 0) and (i < ((self.subtype_row.n + 0x80000000 & 0xFFFFFFFF) - 0x80000000)):
            r = self.subtype_row.a[i & 0xFFFFFFFFFFFFFFFF]
            if ((r >= 0) and (r < self.storages.count())) and (self.storages.node_idx.a[r & 0xFFFFFFFFFFFFFFFF] == i):
                return r
        return (-1)


    def outfall_row(self, i):
        if (i >= 0) and (i < ((self.subtype_row.n + 0x80000000 & 0xFFFFFFFF) - 0x80000000)):
            r = self.subtype_row.a[i & 0xFFFFFFFFFFFFFFFF]
            if ((r >= 0) and (r < self.outfalls.count())) and (self.outfalls.node_idx.a[r & 0xFFFFFFFFFFFFFFFF] == i):
                return r
        return (-1)


    def divider_row(self, i):
        if (i >= 0) and (i < ((self.subtype_row.n + 0x80000000 & 0xFFFFFFFF) - 0x80000000)):
            r = self.subtype_row.a[i & 0xFFFFFFFFFFFFFFFF]
            if ((r >= 0) and (r < self.dividers.count())) and (self.dividers.node_idx.a[r & 0xFFFFFFFFFFFFFFFF] == i):
                return r
        return (-1)



