class SpeciesRegistry(ICopy):
    __slots__ = ('name_', 'kind_', 'units_', 'n_pollutants_', )

    def __init__(self):
        self.name_ = None
        self.kind_ = None
        self.units_ = None
        self.n_pollutants_ = 0

    def m__init_rSpeciesRegistry(self, p):
        self.name_ = p.name_.Clone()
        self.kind_ = p.kind_.Clone()
        self.units_ = p.units_.Clone()
        self.n_pollutants_ = p.n_pollutants_


    def m__init_mSpeciesRegistry(self, p):
        self.MoveFrom(p)


    def m__init_d(self):
        self.name_ = NewVec(NewStr)
        self.kind_ = NewVecI()
        self.units_ = NewVec(NewStr)
        self.n_pollutants_ = 0


    def _ctor(self):
        self.m__init_d()

    def Clone(self):
        o = SpeciesRegistry()
        o.m__CopyFrom_SpeciesRegistry(self)
        return o


    def m__CopyFrom_SpeciesRegistry(self, s):
        self.name_ = None if s.name_ is None else s.name_.Clone()
        self.kind_ = None if s.kind_ is None else s.kind_.Clone()
        self.units_ = None if s.units_ is None else s.units_.Clone()
        self.n_pollutants_ = s.n_pollutants_


    def Assign(self, s):
        if self is s:
            return
        self.name_.Assign_VecT(s.name_)
        self.kind_.Assign_VecT(s.kind_)
        self.units_.Assign_VecT(s.units_)
        self.n_pollutants_ = s.n_pollutants_


    def MoveFrom(self, s):
        if self is s:
            return
        self.name_ = s.name_
        s.name_ = NewVec(NewStr)
        self.kind_ = s.kind_
        s.kind_ = NewVecI()
        self.units_ = s.units_
        s.units_ = NewVec(NewStr)
        self.n_pollutants_ = s.n_pollutants_


    def clear(self):
        self.name_.clear()
        self.kind_.clear()
        self.units_.clear()
        self.n_pollutants_ = 0


    def add(self, name, kind, units):
        name = Cell(name)
        units = Cell(units)
        if self.find(name.v.Clone()) >= 0:
            return (-1)
        self.name_.push_back(Mv_Take(name, NewStr))
        self.kind_.push_back(kind)
        self.units_.push_back(Mv_Take(units, NewStr))
        if kind == 0:
            self.n_pollutants_ += 1
        return (((((self.name_.n + 0x80000000 & 0xFFFFFFFF) - 0x80000000) - 1) + 0x80000000 & 0xFFFFFFFF) - 0x80000000)


    def find(self, name):
        i = 0
        while i < self.name_.n:
            if name.Clone().Equals_Str(self.name_.a[i].Clone()):
                return ((i + 0x80000000 & 0xFFFFFFFF) - 0x80000000)
            i += 1
        return (-1)


    def pollutant_count(self):
        return self.n_pollutants_


    def name(self, i):
        return self.name_.a[i & 0xFFFFFFFFFFFFFFFF]



