class exfil_ExfilSolver(ICopy):
    __slots__ = ('soa_', )

    def __init__(self):
        self.soa_ = None

    def init(self, ctx):
        nodes = ctx.nodes
        n_nodes = nodes.count()
        n_exfil = 0
        i = 0
        for i in range(0, n_nodes):
            ui = i
            sr = ctx.node_subtypes.storage_row(i)
            ksat = (F_lidnode_bottomConductivity(ctx, sr) if (sr >= 0) else 0.0)
            if (nodes.type_.a[ui] == 3) and (ksat > 0.0):
                n_exfil += 1
        if n_exfil == 0:
            self.soa_.count = 0
            return
        self.soa_.resize(n_exfil)
        BIG = 10000000000.0
        k = 0
        i_2 = 0
        for i_2 in range(0, n_nodes):
            ui_2 = i_2
            sr_2 = ctx.node_subtypes.storage_row(i_2)
            exf_suction = (ctx.node_subtypes.storages.exfil_suction.a[sr_2 & 0xFFFFFFFFFFFFFFFF] if (sr_2 >= 0) else 0.0)
            exf_ksat = (F_lidnode_bottomConductivity(ctx, sr_2) if (sr_2 >= 0) else 0.0)
            exf_imd = (ctx.node_subtypes.storages.exfil_imd.a[sr_2 & 0xFFFFFFFFFFFFFFFF] if (sr_2 >= 0) else 0.0)
            if (nodes.type_.a[ui_2] != 3) or (exf_ksat <= 0.0):
                continue
            uk = (k & 0xFFFFFFFFFFFFFFFF)
            self.soa_.node_idx.a[uk] = i_2
            F_infil_grnampt_init(self.soa_.btm_ga.a[uk], exf_suction, exf_ksat, exf_imd, ctx.options)
            F_infil_grnampt_init(self.soa_.bank_ga.a[uk], exf_suction, exf_ksat, exf_imd, ctx.options)
            curve_idx = (ctx.node_subtypes.storages.curve.a[sr_2 & 0xFFFFFFFFFFFFFFFF] if (sr_2 >= 0) else (-1))
            if curve_idx >= 0:
                curve = ctx.tables.op_Index__i(curve_idx)
                self.soa_.btm_area.a[uk] = F_table_lookupEx(curve, 0.0)
                self.soa_.bank_min_depth.a[uk] = 0.0
                self.soa_.bank_max_depth.a[uk] = 0.0
                self.soa_.bank_max_area.a[uk] = 0.0
                if not (curve.x.n == 0):
                    alast = curve.y.a[0]
                    ci = 1
                    while ci < curve.x.n:
                        d = curve.x.a[ci]
                        a = curve.y.a[ci]
                        if a < alast:
                            break
                        elif a > alast:
                            self.soa_.bank_max_area.a[uk] = a
                            self.soa_.bank_max_depth.a[uk] = d
                        elif self.soa_.bank_max_area.a[uk] == 0.0:
                            self.soa_.bank_min_depth.a[uk] = d
                        else:
                            break
                        alast = a
                        ci += 1
                ucf_len = F_ucf_UCF(3, ctx.options)
                self.soa_.btm_area.a[uk] = _n2 / _d1 if ((_n2 := self.soa_.btm_area.a[uk]), (_d1 := ucf_len * ucf_len))[1] else fdiv0(_n2, _d1)
                self.soa_.bank_max_area.a[uk] = _n4 / _d3 if ((_n4 := self.soa_.bank_max_area.a[uk]), (_d3 := ucf_len * ucf_len))[1] else fdiv0(_n4, _d3)
                self.soa_.bank_min_depth.a[uk] = self.soa_.bank_min_depth.a[uk] / ucf_len if ucf_len else fdiv0(self.soa_.bank_min_depth.a[uk], ucf_len)
                self.soa_.bank_max_depth.a[uk] = self.soa_.bank_max_depth.a[uk] / ucf_len if ucf_len else fdiv0(self.soa_.bank_max_depth.a[uk], ucf_len)
            else:
                a_coeff = (ctx.node_subtypes.storages.a.a[sr_2 & 0xFFFFFFFFFFFFFFFF] if (sr_2 >= 0) else 0.0)
                b_coeff = (ctx.node_subtypes.storages.b.a[sr_2 & 0xFFFFFFFFFFFFFFFF] if (sr_2 >= 0) else 0.0)
                c_coeff = (ctx.node_subtypes.storages.c.a[sr_2 & 0xFFFFFFFFFFFFFFFF] if (sr_2 >= 0) else 0.0)
                sshape = (ctx.node_subtypes.storages.shape.a[sr_2 & 0xFFFFFFFFFFFFFFFF] if (sr_2 >= 0) else 1)
                btm = c_coeff
                if F_storage_shape_is_geometric(sshape):
                    pass
                elif b_coeff == 0.0:
                    btm += a_coeff
                self.soa_.btm_area.a[uk] = btm
                self.soa_.bank_min_depth.a[uk] = 0.0
                self.soa_.bank_max_depth.a[uk] = BIG
                self.soa_.bank_max_area.a[uk] = BIG
            k += 1


    def computeAll(self, ctx, dt):
        nodes = ctx.nodes
        k = 0
        while k < self.soa_.count:
            uk = (k & 0xFFFFFFFFFFFFFFFF)
            ni = self.soa_.node_idx.a[uk]
            if ni < 0:
                k += 1
                continue
            uni = (ni & 0xFFFFFFFFFFFFFFFF)
            if F_lidnode_richardsMode(ctx, ni) or (F_lidnode_bottomMode(ctx, ni) != 0):
                ctx.node_subtypes.storages.exfil_rate.a[ctx.node_subtypes.storage_row(ni) & 0xFFFFFFFFFFFFFFFF] = 0.0
                k += 1
                continue
            if (uni < nodes.aquifer2d_bed.n) and (nodes.aquifer2d_bed.a[uni] != 0):
                sr0 = ctx.node_subtypes.storage_row(ni)
                if sr0 >= 0:
                    ctx.node_subtypes.storages.exfil_rate.a[sr0 & 0xFFFFFFFFFFFFFFFF] = 0.0
                k += 1
                continue
            depth = nodes.depth.a[uni]
            total_loss = 0.0
            infil_factor = ctx.climate_state.infil_factor
            recovery_factor = ctx.climate_state.recovery_factor
            def _lam1(ga, d, *, infil_factor=infil_factor, recovery_factor=recovery_factor):
                if ga.IMDmax == 0.0:
                    return (ga.Ks * infil_factor)
                return F_infil_grnampt_getInfil(ga, 0.0, d, dt, 3, infil_factor, recovery_factor)
            ga_rate = _lam1
            total_loss += (ga_rate(self.soa_.btm_ga.a[uk], depth) * self.soa_.btm_area.a[uk]) * F_lidnode_bottomCloggingFactor(ctx, ctx.node_subtypes.storage_row(ni))
            if depth > self.soa_.bank_min_depth.a[uk]:
                area = F_node_getSurfArea(ctx.nodes, self.soa_.node_idx.a[uk], depth, ctx.tables, F_ucf_getUnitSystem(ctx.options.flow_units), ctx.node_subtypes)
                area = (_m2 if (_m2 := self.soa_.bank_max_area.a[uk]) < area else area) - self.soa_.btm_area.a[uk]
                if area > 0.0:
                    bank_depth = depth
                    if self.soa_.bank_ga.a[uk].IMDmax != 0.0:
                        if depth > self.soa_.bank_max_depth.a[uk]:
                            bank_depth = (depth - self.soa_.bank_max_depth.a[uk]) + ((self.soa_.bank_max_depth.a[uk] - self.soa_.bank_min_depth.a[uk]) / 2.0)
                        else:
                            bank_depth = (depth - self.soa_.bank_min_depth.a[uk]) / 2.0
                    total_loss += area * ga_rate(self.soa_.bank_ga.a[uk], bank_depth)
            sr = ctx.node_subtypes.storage_row((uni + 0x80000000 & 0xFFFFFFFF) - 0x80000000)
            if sr >= 0:
                ctx.node_subtypes.storages.exfil_rate.a[sr & 0xFFFFFFFFFFFFFFFF] = total_loss
            k += 1


    def m__init_d(self):
        self.soa_ = exfil_ExfilSoA__new()


    def m__init_rExfilSolver(self, p):
        self.m__CopyFrom_ExfilSolver(p)


    def m__init_mExfilSolver(self, p):
        self.MoveFrom(p)


    def _ctor(self):
        self.m__init_d()

    def Clone(self):
        o = exfil_ExfilSolver()
        o.m__CopyFrom_ExfilSolver(self)
        return o


    def m__CopyFrom_ExfilSolver(self, s):
        self.soa_ = None if s.soa_ is None else s.soa_.Clone()


    def Assign(self, s):
        if self is s:
            return
