    def trackAcceptedWater(self, enabled):
        self.water_tracking_ = enabled
        if enabled and (self.mesh_ is not None):
            self.water_.resize(self.mesh_.n_faces() & 0xFFFFFFFFFFFFFFFF, self.mesh_.struct_link.n, self.mesh_.n_cells() & 0xFFFFFFFFFFFFFFFF, self.mesh_.n_nodes() & 0xFFFFFFFFFFFFFFFF)
        else:
            _o1 = fv_AcceptedWaterVolumes__new()
            _o1.face_forward = NewVecD()
            _o1.face_reverse = NewVecD()
            _o1.structure_forward = NewVecD()
            _o1.structure_reverse = NewVecD()
            _o1.cell_lateral = NewVecD()
            _o1.cell_loss = NewVecD()
            _o1.node_deficit = NewVecD()
            _o1.face_lateral_left = NewVecD()
            _o1.face_lateral_right = NewVecD()
            _o1.face_spill = NewVecD()
            self.water_.MoveFrom(_o1)
        self.save_water_.Assign(self.water_)
        self.rk_water_.Assign(self.water_)


    def acceptedWater(self):
        return self.water_


