    def deriveFaceGeom(self):
        if self.face_geom.n == (self.n_faces() & 0xFFFFFFFFFFFFFFFF):
            return
        self.face_geom.assign_ul_T(self.n_faces() & 0xFFFFFFFFFFFFFFFF, 0)
        f = 0
        while f < self.n_faces():
            uf = (f & 0xFFFFFFFFFFFFFFFF)
            c = (ArrRef(self.face_cl.a, uf) if (self.face_cl.a[uf] >= 0) else ArrRef(self.face_cr.a, uf)).v
            self.face_geom.a[uf] = self.cell_geom.a[c & 0xFFFFFFFFFFFFFFFF] if ((c >= 0) and ((c & 0xFFFFFFFFFFFFFFFF) < self.cell_geom.n)) else 0
            f += 1


    def n_chains(self):
        return (((0 if (self.chain_ptr.n == 0) else (((self.chain_ptr.n + 0x80000000 & 0xFFFFFFFF) - 0x80000000) - 1)) + 0x80000000 & 0xFFFFFFFF) - 0x80000000)


    def n_cells(self):
        return ((self.cell_dx.n + 0x80000000 & 0xFFFFFFFF) - 0x80000000)


    def n_faces(self):
        return ((self.face_cl.n + 0x80000000 & 0xFFFFFFFF) - 0x80000000)


    def n_nodes(self):
        return ((self.node_invert.n + 0x80000000 & 0xFFFFFFFF) - 0x80000000)


    def n_conduits(self):
        return ((self.conduit_cell_begin.n + 0x80000000 & 0xFFFFFFFF) - 0x80000000)


