class groundwater_GWSolver(ICopy):
    __slots__ = ('soa_', )

    def __init__(self):
        self.soa_ = None

    def init(self, n_subcatch):
        self.soa_.resize(n_subcatch)


    def execute(self, ctx, dt, max_evap, infil_rate, sw_head, frac_perv, perv_evap_rate, evap_pattern_month):
        process_timer = perf_ProcessTimer_New_ProcessPhase(20)
        n = self.soa_.n_subcatch
        if n == 0:
            return
        def _lam7(i):
            ui = (i & 0xFFFFFFFFFFFFFFFF)
            if self.soa_.total_depth.a[ui] <= 0.0:
                self.soa_.gw_flow.a[ui] = 0.0
                self.soa_.upper_evap.a[ui] = 0.0
                self.soa_.lower_evap.a[ui] = 0.0
                self.soa_.deep_loss.a[ui] = 0.0
                return
            if frac_perv.get_Item_i(i) <= 0.0:
                return
            c = groundwater_GWContext__new()
            c.porosity = self.soa_.porosity.a[ui]
            c.field_cap = self.soa_.field_cap.a[ui]
            c.wilt_point = self.soa_.wilt_point.a[ui]
            c.k_sat = self.soa_.k_sat.a[ui]
            c.k_slope = self.soa_.k_slope.a[ui]
            c.tension_slope = self.soa_.tension_slope.a[ui]
