class SubcatchSnapshot(ICopy):
    __slots__ = ('snow_process', 'rainfall', 'snow_depth', 'evap', 'infil', 'runoff', 'gw_flow', 'gw_elev', 'soil_moist', )

    def __init__(self):
        self.snow_process = None
        self.rainfall = None
        self.snow_depth = None
        self.evap = None
        self.infil = None
        self.runoff = None
        self.gw_flow = None
        self.gw_elev = None
        self.soil_moist = None

    def m__init_rSubcatchSnapshot(self, p):
        self.m__CopyFrom_SubcatchSnapshot(p)


