        self.snow_process = Mv_Take(FR_SubcatchSnapshot_snow_process(p), NewVecD)
        self.rainfall = Mv_Take(FR_SubcatchSnapshot_rainfall(p), NewVecD)
        self.snow_depth = Mv_Take(FR_SubcatchSnapshot_snow_depth(p), NewVecD)
        self.evap = Mv_Take(FR_SubcatchSnapshot_evap(p), NewVecD)
        self.infil = Mv_Take(FR_SubcatchSnapshot_infil(p), NewVecD)
        self.runoff = Mv_Take(FR_SubcatchSnapshot_runoff(p), NewVecD)
        self.gw_flow = Mv_Take(FR_SubcatchSnapshot_gw_flow(p), NewVecD)
        self.gw_elev = Mv_Take(FR_SubcatchSnapshot_gw_elev(p), NewVecD)
        self.soil_moist = Mv_Take(FR_SubcatchSnapshot_soil_moist(p), NewVecD)


