        v__b1 = [wall_end.v]
        Mv_Back__LL(R_time_Ptrl(NewPtrL_TA_l(v__b1, 0)), wall_end, v__b1)
        wall_start = Cell((FR_SimulationContext_wall_start(ctx) if (ctx.wall_start != 0) else wall_end).v)
        v__b2 = [wall_start.v]
        ct = Mv_Back__OL(R_ctime_Ptrl(NewPtrL_TA_l(v__b2, 0)), wall_start, v__b2)
        if not ct.get_IsNull():
            R_strncpy(begin_str, ct, 63)
