def HotStartManager_save(ctx, path):
    F_tl_last_io_error_HotStartManager.clear()
    if ((ctx.state_accessors.has_fv_retained_dry_mass is not None) and ctx.state_accessors.has_fv_retained_dry_mass()) and (not (ctx.state_accessors.get_fv_dry_state is not None)):
        F_tl_last_io_error_HotStartManager.Assign_CPtr(R_Lit('Hotstart cannot preserve retained FV dry scalar inventory; save after it remobilizes.'))
        return None
    if not (ctx.reactions.lid_controls.n == 0):
        F_tl_last_io_error_HotStartManager.Assign_CPtr(R_Lit('LID reaction inventories require a full native engine checkpoint'))
        return None
    if F__anon_core_HotStartManager_cpp_independentGroundwaterRestart_HotStartManager(ctx):
        F_tl_last_io_error_HotStartManager.Assign_CPtr(R_Lit('Independent groundwater hotstart needs the complete routing and surface clocks. Start a checkpoint session or configure a native SAVE HOTSTART before starting the run.'))
        return None
    if F__anon_core_HotStartManager_cpp_coupledThermalRestartUnsupported_HotStartManager(ctx):
        F_tl_last_io_error_HotStartManager.Assign_CPtr(R_Lit('Coupled mesh/ground heat hotstart requires its thermal energy restart extension'))
        return None
    if F__anon_core_HotStartManager_cpp_meshLidRestartUnsupported_HotStartManager(ctx):
        F_tl_last_io_error_HotStartManager.Assign_CPtr(R_Lit('Mesh LID hotstart requires the R5 joint owner restart extension'))
        return None
    if ctx.runtime_coupling_used:
        F_tl_last_io_error_HotStartManager.Assign_CPtr(R_Lit('Hotstart cannot preserve runtime 2D coupling prescriptions and receipts'))
        return None
    use_v2 = ctx.state_accessors.can_read()
    hs = HotStartFile__new()
    hs.path.Assign_Str(path)
    hs.header.version = 3 if ctx.options.water_age else (2 if use_v2 else 1)
    if F__anon_core_HotStartManager_cpp_captureSpeciesBlock_HotStartManager(ctx, hs):
        hs.header.version = 4
    if F__anon_core_HotStartManager_cpp_captureAquiferBlock_HotStartManager(ctx, hs):
        hs.header.version = 5
        if F__anon_core_HotStartManager_cpp_captureAquiferSpeciesBlock_HotStartManager(ctx, hs):
            hs.header.version = 6
            i = 0
            while i < hs.gw_species.n:
                if (hs.gw_species_ledger.a[((i * (HotStartFile_kGwSpeciesLedgerTerms & 0xFFFFFFFFFFFFFFFF)) + 11) & 0xFFFFFFFFFFFFFFFF] != 0.0) or (hs.gw_species_ledger.a[((i * (HotStartFile_kGwSpeciesLedgerTerms & 0xFFFFFFFFFFFFFFFF)) + 12) & 0xFFFFFFFFFFFFFFFF] != 0.0):
                    hs.header.version = 7
                i += 1
    hs.header.timestamp = R_time_Ptrl(PtrL_ZERO)
    hs.header.sim_time = ctx.current_time
    hs.header.start_date = ctx.options.start_date
    hs.header.end_date = ctx.options.end_date
    hs.header.crs.Assign_Str(ctx.spatial.crs)
    n_nodes = ctx.n_nodes()
    hs.nodes.resize_ul(n_nodes & 0xFFFFFFFFFFFFFFFF)
    i_2 = 0
    for i_2 in range(0, n_nodes):
        ui = i_2
        hs.nodes.a[ui].id.Assign_Str(ctx.node_names.name_of(i_2))
        hs.nodes.a[ui].depth = ctx.nodes.depth.a[ui]
        hs.nodes.a[ui].head = ctx.nodes.head.a[ui]
        hs.nodes.a[ui].volume = ctx.nodes.volume.a[ui]
        if F_lidnode_active(ctx, i_2):
            hs.header.version = 10 if hs.header.version < 10 else hs.header.version
            state = ctx.node_subtypes.storages.lid_state.a[ctx.node_subtypes.storage_row(i_2) & 0xFFFFFFFFFFFFFFFF]
            hs.nodes.a[ui].lid_treated_volume = state.treated_volume
            hs.nodes.a[ui].lid_quality_mass.Assign_VecT(state.quality_mass)
            if state.richards:
                hs.header.version = 11
                stack = F_lidnode_layers(ctx, ctx.node_subtypes.storages.lid.a[ctx.node_subtypes.storage_row(i_2) & 0xFFFFFFFFFFFFFFFF].control)
                k = 0
                while k < state.cells.n:
                    cell = state.cells.a[k]
                    p = stack.a[(((cell.layer - 1) + 0x80000000 & 0xFFFFFFFF) - 0x80000000) & 0xFFFFFFFFFFFFFFFF].retention
                    values = hs.nodes.a[ui].lid_richards
                    values.insert_IterT_TA(values.end().Clone(), [state.richards_water.a[k], p.theta_r, p.alpha, p.n, p.l, p.specific_storage, cell.conductivity, cell.wilting_point])
                    k += 1
            if state.infiltration_cell >= 0:
                ga = state.surface_infil
                hs.nodes.a[ui].lid_infiltration.MoveFrom_TA([ga.S, ga.Ks, ga.IMDmax, ga.IMD, ga.F, ga.Fu, ga.Fumax, ga.Lu, ga.T, state.infiltration_head, 1.0 if ga.saturated else 0.0])
            v__r1 = state.cells
            v__i2_n = v__r1.n
            for v__i2 in range(0, v__i2_n):
                c = v__r1.a[v__i2]
                _o1 = HotStartLidCellRecord__new()
                _o1.layer = c.layer
                _o1.bottom = c.bottom
                _o1.top = c.top
                _o1.porosity = c.porosity
                _o1.volume = c.geometric_volume
                _o1.theta = c.theta
                hs.nodes.a[ui].lid_cells.push_back(_o1)
        if ctx.options.water_age and (ui < ctx.water_age_state.node_age.n):
            hs.nodes.a[ui].age = ctx.water_age_state.node_age.a[ui]
    n_links = ctx.n_links()
    hs.links.resize_ul(n_links & 0xFFFFFFFFFFFFFFFF)
    i_3 = 0
    for i_3 in range(0, n_links):
        ui_2 = i_3
        hs.links.a[ui_2].id.Assign_Str(ctx.link_names.name_of(i_3))
        hs.links.a[ui_2].flow = ctx.links.flow.a[ui_2]
        hs.links.a[ui_2].depth = ctx.links.depth.a[ui_2]
