def ucf_DisplayUnits_from_(opts):
    d = ucf_DisplayUnits__new()
    fu = opts.flow_units
    if (fu < 0) or (fu > 5):
        fu = 0
    us = F_ucf_getUnitSystem(fu)
    si = (us == 1)
    d.unit_system = us
    d.flow_units = fu
    d.flow = F_ucf_Qcf_UnitConversion[fu]
    d.length = F_ucf_Ucf_UnitConversion[3][us]
    d.volume = F_ucf_Ucf_UnitConversion[5][us]
    d.rainfall = F_ucf_Ucf_UnitConversion[0][us]
    d.raindepth = F_ucf_Ucf_UnitConversion[1][us]
    d.evaprate = F_ucf_Ucf_UnitConversion[2][us]
    d.landarea = F_ucf_Ucf_UnitConversion[4][us]
    d.mvol = 2.83168E-05 if si else F_ucf_FT3_TO_MGAL_UnitConversion
    d.landvol = 2.83168E-06 if si else (1.0 / F_ucf_ACRES_TO_FT2_UnitConversion if F_ucf_ACRES_TO_FT2_UnitConversion else fdiv0(1.0, F_ucf_ACRES_TO_FT2_UnitConversion))
    d.flow_word = F_ucf_FlowUnitWords[fu]
    d.length_word = R_Lit('Meters') if si else R_Lit('Feet')
    d.depth_word = R_Lit('mm') if si else R_Lit('in')
    d.vel_word = R_Lit('m/sec') if si else R_Lit('ft/sec')
    d.mvol_word = R_Lit('10^6 ltr') if si else R_Lit('10^6 gal')
    d.landvol_word = R_Lit('hectare-m') if si else R_Lit('acre-feet')
    d.storage_vol_word = R_Lit('1000 m3') if si else R_Lit('1000 ft3')
    return ucf_DisplayUnits_MoveNew(d)


