def fv_PressurizedHeadSolver_cellPressurized(mesh, state, cell):
    uc = (cell & 0xFFFFFFFFFFFFFFFF)
    if not (state.cell_tpa.n == 0):
        return (state.cell_tpa.a[uc] != 0)
    g = mesh.geom.a[mesh.cell_geom.a[uc] & 0xFFFFFFFFFFFFFFFF]
    return ((not (g.is_open != 0)) and (state.cell_h.a[uc] >= g.y_crown))


def fv_PressurizedHeadSolver_faceModeOf(mesh, state, f):
    uf = (f & 0xFFFFFFFFFFFFFFFF)
    if mesh.face_gate.a[uf] != 0:
        return 0
    if mesh.face_culvert.a[uf] >= 0:
        return 0
    cl = mesh.face_cl.a[uf]
    cr = mesh.face_cr.a[uf]
    nd = mesh.face_node.a[uf]
    if (nd < 0) and ((cl < 0) or (cr < 0)):
        return 0
    pl = False
    pr = False
    cell_side_press = False
    if cl >= 0:
        pl = fv_PressurizedHeadSolver_cellPressurized(mesh, state, cl)
        cell_side_press = cell_side_press or pl
    if cr >= 0:
        pr = fv_PressurizedHeadSolver_cellPressurized(mesh, state, cr)
        cell_side_press = cell_side_press or pr
    if nd >= 0:
        gp = fv_PressurizedHeadSolver_ghostPressurized(mesh, state, f)
        if cl < 0:
            pl = gp
        if cr < 0:
            pr = gp
    if not cell_side_press:
        return 0
    return ((1 if (pl and pr) else 2) & 0xFF)


def fv_PressurizedHeadSolver_ghostPressurized(mesh, state, f):
    uf = (f & 0xFFFFFFFFFFFFFFFF)
    nd = mesh.face_node.a[uf]
    if nd < 0:
        return False
    other = (ArrRef(mesh.face_cl.a, uf) if (mesh.face_cl.a[uf] >= 0) else ArrRef(mesh.face_cr.a, uf)).v
    if other < 0:
        return False
    g = mesh.geom.a[mesh.cell_geom.a[other & 0xFFFFFFFFFFFFFFFF] & 0xFFFFFFFFFFFFFFFF]
    if g.is_open != 0:
        return False
    if ((not (state.cell_tpa.n == 0)) and (state.cell_tpa.a[other & 0xFFFFFFFFFFFFFFFF] != 0)) and (mesh.node_sur_depth.a[nd & 0xFFFFFFFFFFFFFFFF] > 0.0):
        return True
    hg = (state.node_head.a[nd & 0xFFFFFFFFFFFFFFFF] - mesh.face_zb.a[uf])
    return (hg >= g.y_crown)


