def rdii_RDIISolver_getRainInterval(uh, wet_step):
    ri = Conv_D2I(wet_step)
    if ri <= 0:
        ri = 300
    m = 0
    for m in range(0, 12):
        k = 0
        for k in range(0, 3):
            tp = uh.tPeak[m][k]
            if tp > 0.0:
                tLimb = Conv_D2I(tp)
                if tLimb > 0:
                    ri = tLimb if tLimb < ri else ri
                tFall = Conv_D2I(uh.tBase[m][k] - tp)
                if tFall > 0:
                    ri = tFall if tFall < ri else ri
    return (1 if ri < 1 else ri)


def rdii_RDIISolver_getMaxPeriods(uh, response, rainInterval):
    if rainInterval <= 0:
        return 0
    k = (response % 3 if response >= 0 else -(-response % 3))
    nMax = 0
    m = 0
    for m in range(0, 12):
        n = (((Conv_D2I(uh.tBase[m][k] / rainInterval if rainInterval else fdiv0(uh.tBase[m][k], rainInterval)) + 1) + 0x80000000 & 0xFFFFFFFF) - 0x80000000)
        nMax = nMax if n < nMax else n
    return nMax


