def runoff_RunoffSolver_updatePondedDepth(depth, inflow, alpha, dStore, dt, t_runoff):
    tx = dt
    if (depth.v + (inflow * tx)) <= dStore:
        depth.v += inflow * tx
    else:
        dx = (dStore - depth.v)
        if (dx > 0.0) and (inflow > 0.0):
            tx -= dx / inflow if inflow else fdiv0(dx, inflow)
            depth.v = dStore
        if (alpha > 0.0) and (tx > 0.0):
            captured_inflow = inflow
            captured_alpha = alpha
            captured_dStore = dStore
            v__b1 = [depth.v]
            v__cap2 = captured_inflow
            v__cap3 = captured_alpha
            v__cap4 = captured_dStore
            _arg2 = NewPtrD_TA_l(v__b1, 0)
            _arg3 = tx
            _arg4 = F_runoff_ODETOL
            _arg5 = tx
            def _lam1(p, d, dddt):
                rx = (d.get_Deref() - v__cap4)
                outflow = ((v__cap3 * Math_Pow_d(rx, F_runoff_MEXP)) if (rx > 0.0) else 0.0)
                dddt.set_Deref(v__cap2 - outflow)
                return
            Mv_Back__ID(F_ode_integrate(_arg2, 1, 0.0, _arg3, _arg4, _arg5, _lam1), depth, v__b1)
        else:
            tx = 0.0 if tx < 0.0 else tx
            depth.v += inflow * tx
    depth.v = 0.0 if depth.v < 0.0 else depth.v
    t_runoff.v = tx


