def snow_DegreeDaySnow_rainMeltRate(temp, wind, gamma, ea, rainfall):
    rainfall = rainfall * 43200.0
    if rainfall > 0.02:
        uadj = (0.006 * wind)
        t1 = (temp - 32.0)
        t2 = ((7.5 * gamma) * uadj)
        t3 = ((8.5 * uadj) * (ea - 0.18))
        smelt = ((t1 * ((0.001167 + t2) + (0.007 * rainfall))) + t3)
        return (smelt / 43200.0)
    return 0.0


