    wMax = Cell(w1.v)
    y2 = Cell(0.0)
    w2 = Cell(0.0)
    ci = Cell(1)
    if y1.v != 0.0:
        y2.v = y1.v
        w2.v = w1.v
        y1.v = 0.0
        w1.v = 0.0
    else:
        if ci.v >= n_pts:
            return
        y2.v = curve_x.get_Item_i(ci.v)
        w2.v = curve_y.get_Item_i(ci.v)
        ci.v += 1
        if (y2.v < y1.v) or (w2.v < 0.0):
            return
        if y2.v > 1.0:
            y2.v = 1.0
        if w2.v > wMax.v:
            wMax.v = w2.v
    n = (((F_transect_N_TRANSECT_TBL - 1) + 0x80000000 & 0xFFFFFFFF) - 0x80000000)
    dy = (1.0 / n if n else fdiv0(1.0, n))
