    td.hrad_tbl[0] = 0.0
    td.width_tbl[0] = w1.v
    Ptotal = Cell(w1.v)
    Atotal = Cell(0.0)
    y = 0.0
    w = w1.v
    i = 1
    for i in range(1, n + 1):
        yLast = y
        wLast = w
        y = y + dy
        if abs(y - 1.0) < 1E-06:
            y = 1.0
        if y > y2.v:
            if not F_transect__anon_hydraulics_Transect_cpp_shapeGetNextInterval_Transect(curve_x, curve_y, n_pts, ci, y, yLast, wLast, y1, y2, w1, w2, wMax, Atotal, Ptotal):
                return
            yLast = y1.v
            wLast = w1.v
        w = F_transect__anon_hydraulics_Transect_cpp_shapeGetWidth_Transect(y, y1.v, y2.v, w1.v, w2.v)
