        entry.month = month
        entry.response = response
        entry.r = F_input_to_double(tok.a[3].Clone(), 0.0)
        entry.t = F_input_to_double(tok.a[4].Clone(), 0.0)
        entry.k = F_input_to_double(tok.a[5].Clone(), 0.0)
